const importedEnemyMeshByName=Object.fromEntries([...importedLightFighterMeshes,...importedEliteHullMeshes].map(m=>[m.name,m]));
function enemyMeshStats(mesh){
 if(mesh._stats)return mesh._stats;
 let maxAbsX=0,maxAbsY=0,minZ=Infinity,maxZ=-Infinity;
 for(const v of mesh.v){maxAbsX=Math.max(maxAbsX,Math.abs(v[0]));maxAbsY=Math.max(maxAbsY,Math.abs(v[1]));minZ=Math.min(minZ,v[2]);maxZ=Math.max(maxZ,v[2])}
 return mesh._stats={maxAbsX,maxAbsY,minZ,maxZ}
}
const importedEnemyFighterRoster=[...importedLightFighterMeshes,...importedEliteHullMeshes];
function pickEnemyFighterMesh(){
 // Both authored packs are currently visual fighter variants.  They share the
 // same AI/stats for now, so changing hull never secretly changes difficulty.
 return importedEnemyFighterRoster[(Math.random()*importedEnemyFighterRoster.length)|0]||fighterMesh
}

