   const a=camPts[i],b=camPts[(i+1)%camPts.length],ain=a[2]>near,bin=b[2]>near;
   if(ain)out.push(a);
   if(ain!==bin){const t=(near-a[2])/(b[2]-a[2]);out.push([lerp(a[0],b[0],t),lerp(a[1],b[1],t),near])}
