 let m=meshEdgeOwners.get(mesh);if(m&&m.faces===faces)return m.owners;
 // A face "owns" an edge when it contains both end vertices (outline or diagonal).
 const vf=new Map();faces.forEach((f,fi)=>{for(const v of f){let l=vf.get(v);if(!l)vf.set(v,l=[]);if(l[l.length-1]!==fi)l.push(fi)}});
