 // Object rotation exactly as rotate(): rx(r0) then ry(r1) then rz(r2).
 const r=obj.rot||[0,0,0],c0=Math.cos(r[0]),s0=Math.sin(r[0]),c1=Math.cos(r[1]),s1=Math.sin(r[1]),c2=Math.cos(r[2]),s2=Math.sin(r[2]);
