   const v=V[i],x=v[0]*kx,y=v[1]*ky,z=v[2]*kz;
   const wx=a00*x+a01*y+a02*z+ox,wy=a10*x+a11*y+a12*z+oy,wz=a20*x+a21*y+a22*z+oz;
   const w=world[i];w[0]=wx;w[1]=wy;w[2]=wz;
   const dx=wx-sxp,dy=wy-syp,dz=wz,q=cam[i];
   const qx=M[0]*dx+M[1]*dy+M[2]*dz,qy=M[3]*dx+M[4]*dy+M[5]*dz,qz=M[6]*dx+M[7]*dy+M[8]*dz;
