   const face=faces[fi];px.length=0;py.length=0;iz.length=0;
   let allIn=true;for(let j=0;j<face.length;j++)if(cam[face[j]][2]<=NEAR){allIn=false;break}
   if(allIn){for(let j=0;j<face.length;j++){const c=cam[face[j]];px.push(CX+c[0]*F/c[2]);py.push(CY-c[1]*F/c[2]);iz.push(1/c[2])}}
