function agentXAnimatedBugMesh(obj){
  const base=obj?.mesh;if(!base?.bugKind||!base.bugAnimGroups?.length)return base;
  const verts=base.v.map(v=>v.slice()),t=performance.now()*.001+(obj.bugAnimPhase||0);
  const hornet=base.bugKind==='hornet',speed=hornet?16.5:5.4,amp=hornet?.58:.26;
  for(const group of base.bugAnimGroups){
    const pivot=base.v[group.pivot],side=Math.sign(pivot[0]||1);
    // Hornet wings flap rapidly; larval proto-legs paddle in a travelling sequence.
    const a=Math.sin(t*speed+(group.phase||0))*amp*side,c=Math.cos(a),s=Math.sin(a);
    for(const index of group.indices){
      const v=base.v[index],dx=v[0]-pivot[0],dy=v[1]-pivot[1];
      verts[index]=[pivot[0]+dx*c-dy*s,pivot[1]+dx*s+dy*c,v[2]]
    }
  }
  return {name:base.name,v:verts,e:base.e,faces:base.faces}
}
function drawAgentXBugPropulsion(obj,col=C.c){
  const base=obj?.mesh;if(!base?.bugKind)return;
  const now=performance.now()*.001+(obj.bugAnimPhase||0),hornet=base.bugKind==='hornet';
  const speed=hornet?4.8:2.4,count=hornet?3:2,tail=base.bugTailZ||.8;
  const projectLocal=p=>{const q=rotate([p[0]*obj.s,p[1]*obj.s,p[2]*obj.s],obj.rot);return projectCam(camPoint([q[0]+obj.x,q[1]+obj.y,q[2]+obj.z]))};
  for(let j=0;j<count;j++){
    const u=((now*speed+j/count)%1),radius=(hornet?.10:.13)+(hornet?.18:.24)*u,z=tail+.08+u*(hornet?.58:.44),alpha=(1-u)*(hornet?.62:.50);
    const pts=[];
    for(let i=0;i<8;i++){const a=i*Math.PI*2/8;pts.push(projectLocal([Math.cos(a)*radius,Math.sin(a)*radius*.58,z]))}
    for(let i=0;i<8;i++){const a=pts[i],b=pts[(i+1)%8];if(a&&b)line(a.x,a.y,b.x,b.y,col,.9,alpha)}
  }
}
function drawAgentXSpaceBug(obj,col){
  const mesh=agentXAnimatedBugMesh(obj)||obj.mesh;
  drawMesh(obj,mesh,col);
  drawAgentXBugPropulsion(obj,obj.mesh?.propulsionCol||C.c)
}


