// Cut a genuine secure delivery hatch into the right-hand front wall. The original
// wall component is vertices 32..39; it is replaced by four battered wall solids
// around the opening so hidden-line removal sees an actual aperture rather than a
// decorative rectangle painted over an intact wall.
(function addOsdDeliveryHatchOpening(mesh){
  const removed=new Set([32,33,34,35,36,37,38,39]);
  mesh.e=(mesh.e||[]).filter(ed=>!removed.has(ed[0])&&!removed.has(ed[1]));
  mesh.faces=(mesh.faces||[]).filter(face=>!face.some(i=>removed.has(i)));
  const zFront=y=>-1.74+(0.05/0.76)*y;
  const zBack=y=>-1.42-(0.05/0.76)*y;
  const addWallBlock=(x0,x1,y0,y1)=>{
    const b=mesh.v.length;
    mesh.v.push(
      [x0,y0,zFront(y0)],[x1,y0,zFront(y0)],[x1,y0,zBack(y0)],[x0,y0,zBack(y0)],
      [x0,y1,zFront(y1)],[x1,y1,zFront(y1)],[x1,y1,zBack(y1)],[x0,y1,zBack(y1)]
    );
    mesh.e.push(
      [b,b+1],[b+1,b+2],[b+2,b+3],[b+3,b],
      [b+4,b+5],[b+5,b+6],[b+6,b+7],[b+7,b+4],
      [b,b+4],[b+1,b+5],[b+2,b+6],[b+3,b+7]
    );
    mesh.faces.push(
      [b,b+1,b+2,b+3],[b+4,b+5,b+6,b+7],
      [b,b+1,b+5,b+4],[b+1,b+2,b+6,b+5],
      [b+2,b+3,b+7,b+6],[b+3,b,b+4,b+7]
    )
  };
  const hx0=.99,hx1=1.57,hy0=.06,hy1=.64;
  addWallBlock(.62,hx0,0,.76);
  addWallBlock(hx1,2.05,0,.76);
  addWallBlock(hx0,hx1,0,hy0);
  addWallBlock(hx0,hx1,hy1,.76);
  mesh.deliveryHatch={x:(hx0+hx1)*.5,y:(hy0+hy1)*.5,z:zFront((hy0+hy1)*.5)-.004,width:hx1-hx0,height:hy1-hy0,innerZ:-1.12};
})(osdTwinTowerFortressMesh);

